// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { ArrowUp, FileText, Loader2, Mic, Paperclip, Square, X } from "lucide-react";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Props                                                               */
/* ------------------------------------------------------------------ */

export interface AIChatInputProps {
  /** Controlled value. Omit it to let the component manage its own text. */
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Fired on Enter or when the send button is pressed. */
  onSubmit?: (value: string, files: File[]) => void;
  /** While loading, the send button becomes a stop button if this is provided. */
  onStop?: () => void;
  onVoiceClick?: () => void;
  onFilesChange?: (files: File[]) => void;
  isLoading?: boolean;
  /** Controlled mic state. Omit it for a built-in visual toggle. */
  isListening?: boolean;
  disabled?: boolean;
  placeholder?: string;
  /** Small helper text under the input. Pass an empty string to hide it. */
  hint?: string;
  /** Passed to the hidden file input, e.g. "image/*,.pdf". */
  accept?: string;
  /** Maximum textarea height in px before it scrolls. */
  maxHeight?: number;
  showAttachment?: boolean;
  showVoice?: boolean;
  className?: string;
}



/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const formatSize = (bytes: number) =>
  bytes < 1024 ? `${bytes} B` : bytes < 1048576 ? `${(bytes / 1024).toFixed(0)} KB` : `${(bytes / 1048576).toFixed(1)} MB`;

// Shared classes for the small round icon buttons
const iconButton =
  "inline-flex size-9 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-colors " +
  "hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring " +
  "disabled:pointer-events-none disabled:opacity-50";



/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export function AIChatInput({
  value,
  defaultValue = "",
  onChange,
  onSubmit,
  onStop,
  onVoiceClick,
  onFilesChange,
  isLoading = false,
  isListening,
  disabled = false,
  placeholder = "Ask anything…",
  hint = "Enter to send · Shift + Enter for a new line",
  accept,
  maxHeight = 200,
  showAttachment = true,
  showVoice = true,
  className,
}: AIChatInputProps) {
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  // Works both controlled (value + onChange) and uncontrolled
  const isControlled = value !== undefined;
  const [innerValue, setInnerValue] = React.useState(defaultValue);
  const text = isControlled ? value : innerValue;

  const [files, setFiles] = React.useState<File[]>([]);
  const [localListening, setLocalListening] = React.useState(false);
  const listening = isListening ?? localListening;

  const hasContent = text.trim().length > 0 || files.length > 0;
  const canSubmit = hasContent && !disabled && !isLoading;

  const updateText = (next: string) => {
    if (!isControlled) setInnerValue(next);
    onChange?.(next);
  };

  const updateFiles = (next: File[]) => {
    setFiles(next);
    onFilesChange?.(next);
  };

  // Grow the textarea with its content, up to maxHeight
  React.useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, maxHeight)}px`;
  }, [text, maxHeight]);

  const submit = () => {
    if (!canSubmit) return;
    onSubmit?.(text.trim(), files);
    updateText("");
    updateFiles([]);
  };

  // Enter sends, Shift+Enter adds a line, and IME composition is left alone
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
  };

  const handleFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    const picked = Array.from(e.target.files ?? []);
    if (picked.length) updateFiles([...files, ...picked]);
    e.target.value = ""; // allow picking the same file again
  };

  const handleVoice = () => {
    onVoiceClick?.();
    if (isListening === undefined) setLocalListening((v) => !v);
  };

  return (
    <div className={cn("w-full", className)}>
      <div
        className={cn(
          "rounded-3xl border border-border bg-card p-2 shadow-sm transition-all",
          "focus-within:border-ring/60 focus-within:ring-4 focus-within:ring-ring/10",
          disabled && "opacity-60"
        )}
      >
        {/* Attachment previews */}
        {files.length > 0 && (
          <ul className="flex flex-wrap gap-2 px-2 pb-1 pt-2">
            {files.map((file, i) => (
              <li
                key={`${file.name}-${i}`}
                className="flex max-w-full items-center gap-2 rounded-xl border border-border bg-muted/50 py-1.5 pl-2.5 pr-1.5 text-xs"
              >
                <FileText className="size-4 shrink-0 text-muted-foreground" />
                <span className="max-w-[10rem] truncate font-medium text-foreground">{file.name}</span>
                <span className="text-muted-foreground">{formatSize(file.size)}</span>
                <button
                  type="button"
                  aria-label={`Remove ${file.name}`}
                  onClick={() => updateFiles(files.filter((_, idx) => idx !== i))}
                  className="grid size-5 place-items-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <X className="size-3" />
                </button>
              </li>
            ))}
          </ul>
        )}

        {/* Text area */}
        <textarea
          ref={textareaRef}
          value={text}
          rows={1}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={placeholder}
          onChange={(e) => updateText(e.target.value)}
          onKeyDown={handleKeyDown}
          className="block w-full resize-none bg-transparent px-3 py-2.5 text-[15px] leading-6 text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
        />

        {/* Toolbar */}
        <div className="flex items-center justify-between gap-2 px-1 pt-1">
          <div className="flex items-center gap-1">
            {showAttachment && (
              <>
                <input ref={fileInputRef} type="file" multiple accept={accept} hidden onChange={handleFiles} />
                <button
                  type="button"
                  aria-label="Attach files"
                  disabled={disabled}
                  onClick={() => fileInputRef.current?.click()}
                  className={iconButton}
                >
                  <Paperclip className="size-[18px]" />
                </button>
              </>
            )}
            {showVoice && (
              <button
                type="button"
                aria-label={listening ? "Stop voice input" : "Start voice input"}
                aria-pressed={listening}
                disabled={disabled}
                onClick={handleVoice}
                className={cn(iconButton, listening && "bg-destructive/10 text-destructive hover:bg-destructive/15 hover:text-destructive")}
              >
                <Mic className={cn("size-[18px]", listening && "animate-pulse")} />
              </button>
            )}
            {listening && <span className="pl-1 text-xs text-muted-foreground" role="status">Listening…</span>}
          </div>

          {/* Send button: lights up once there is something to send */}
          {isLoading && onStop ? (
            <button
              type="button"
              aria-label="Stop generating"
              onClick={onStop}
              className="inline-flex size-9 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-sm transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              <Square className="size-3.5 fill-current" />
            </button>
          ) : (
            <button
              type="button"
              aria-label="Send message"
              disabled={!canSubmit}
              onClick={submit}
              className={cn(
                "inline-flex size-9 items-center justify-center rounded-full transition-all",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                canSubmit
                  ? "bg-primary text-primary-foreground shadow-md hover:scale-105 hover:opacity-90 active:scale-95"
                  : "bg-muted text-muted-foreground",
                !canSubmit && !isLoading && "cursor-not-allowed"
              )}
            >
              {isLoading ? <Loader2 className="size-4 animate-spin" /> : <ArrowUp className="size-[18px]" strokeWidth={2.5} />}
            </button>
          )}
        </div>
      </div>

      {hint && <p className="mt-2 hidden text-center text-xs text-muted-foreground sm:block">{hint}</p>}
    </div>
  );
}

